SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, AVG(temp_c) OVER (PARTITION BY TO_DATE(reading_ts), device_code ORDER BY temp_c, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS temp_c_avg_5, AVG(pressure) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS pressure_avg_2, CORR(pressure, temp_c) OVER (PARTITION BY device_code) AS corr_pressure_temp_c, STDDEV_SAMP(pressure) OVER (PARTITION BY device_code) AS device_code_stddev_samp_pressure FROM device_readings;
